import numpy as np
import os, sys
sys.path.append('storage/verity')
try:
    import sqp_core as sqp
except Exception as e:
    sqp = None

N = 32

def _seed_grid_minus_corners():
    xs = np.linspace(0.1, 0.9, 6)
    ys = np.linspace(0.1, 0.9, 6)
    centers = []
    for ix, X in enumerate(xs):
        for iy, Y in enumerate(ys):
            if (ix in (0,5)) and (iy in (0,5)):
                continue
            centers.append([X, Y])
    return np.array(centers, dtype=float)

def _load_baseline():
    C = None
    try:
        C = np.load("storage/verity/best_centers.npy")
        if not (isinstance(C, np.ndarray) and C.shape == (N,2)):
            C = None
    except Exception:
        C = None
    if C is None:
        C = _seed_grid_minus_corners()
    C = np.clip(C.astype(float), 0.0, 1.0)
    s0, r0 = sqp.merit_sum_r(C)
    r0 = np.array(r0, dtype=float)
    return C, r0, s0

def construct_packing() -> tuple:
    if sqp is None:
        # Fallback: return a safe baseline grid solution
        C = _seed_grid_minus_corners()
        s0, r0 = 0.0, np.zeros(N, dtype=float)
        try:
            s0, r0 = (0.0, np.maximum(1e-8, np.minimum.reduce([C[:,0], 1.0-C[:,0], C[:,1], 1.0-C[:,1]])))
        except Exception:
            pass
        print("[SQP v0] fallback path (module import failed)")
        return C, r0

    C, r, s = _load_baseline()
    print(f"[SQP v0] start sum={s:.15f}")

    best_C, best_r, best_s = C.copy(), r.copy(), float(s)
    accepts = 0
    noimp = 0
    max_outer = 30
    # Thinned basis: even-index circles only (deterministic)
    basis_idx = list(range(0, N, 2))

    for it in range(max_outer):
        improved, C1, R1, S1, info = sqp.step_sqp(best_C, basis_idx=basis_idx)
        print(f"[SQP v0] it={it:02d} s0={info['s0']:.15f} s1={info['s_new']:.15f} "
              f"act_pairs={info['n_act_pair']} A_shape={info['A_shape']}")
        if improved:
            best_C, best_r, best_s = C1, R1, S1
            accepts += 1
            noimp = 0
            # Rotate basis deterministically to vary finite-difference support
            shift = (it + 1) % 2
            basis_idx = list(range(shift, N, 2))
        else:
            noimp += 1
            if noimp >= 5:
                break

        if accepts >= 8:
            break

    # Persist only if strictly improved
    if best_s > s + 5e-10:
        try:
            os.makedirs("storage/verity", exist_ok=True)
            np.save("storage/verity/best_centers.npy", best_C)
            np.save("storage/verity/best_radii.npy", best_r)
            print(f"[SQP v0] persisted improved packing sum={best_s:.15f}")
        except Exception:
            pass

    return np.array(best_C, dtype=float), np.array(best_r, dtype=float)
